import re

STRONG_VERBS = {"built", "designed", "implemented", "led", "migrated", "reduced", "improved", "shipped",
                "automated", "debugged", "wrote", "owned", "integrated", "optimized", "launched", "developed"}
WEAK_STARTS = ("responsible for", "worked on", "helped", "involved in", "assisted")
RISKY_CLAIMS = ("production", "at scale", "expert", "led the team", "architected")
NUMBER = re.compile(r"\d")


def audit_bullet(b: dict) -> list:
    """b has: text, evidence (a link, repo path, doc or person who can confirm), metric_source (where a number came from).
    Returns a list of problems. An empty list means the bullet is defensible in an interview."""
    text = b["text"].strip()
    low = text.lower()
    problems = []
    if low.startswith(WEAK_STARTS):
        problems.append("weak opening: start with what you personally did")
    elif low.split()[0].strip(",.") not in STRONG_VERBS:
        problems.append("start with a strong past-tense verb")
    if len(text.split()) > 32:
        problems.append("too long: aim for under 30 words, one idea")
    if not b.get("evidence"):
        problems.append("no evidence: add a repo path, link, document or colleague who can confirm it")
    if NUMBER.search(text) and not b.get("metric_source"):
        problems.append("number without a source: say where it was measured or remove it")
    for claim in RISKY_CLAIMS:
        if claim in low and not b.get("evidence"):
            problems.append(f"'{claim}' needs evidence you can defend line by line")
    if re.search(r"\bwe\b", low):
        problems.append("say what you did, not what the team did")
    return problems


def coverage(jd_requirements: list, resume_skills: set) -> dict:
    """Honest match: which JD requirements you can evidence, and which are gaps to learn or not claim."""
    have = [r for r in jd_requirements if r.lower() in {s.lower() for s in resume_skills}]
    gaps = [r for r in jd_requirements if r not in have]
    return {"covered": have, "gaps": gaps, "score": round(len(have) / max(len(jd_requirements), 1), 2)}


def check() -> None:
    good = {"text": "Built a REST API for order lookups in FastAPI and PostgreSQL, cutting p95 latency from 800 ms to 300 ms",
            "evidence": "repo orders-api, PR 142, Grafana dashboard", "metric_source": "load test run 2025-11, Grafana p95 panel"}
    assert audit_bullet(good) == []

    weak = {"text": "Responsible for working on AI at scale in production", "evidence": ""}
    problems = audit_bullet(weak)
    assert any("weak opening" in p for p in problems)
    assert any("no evidence" in p for p in problems)
    assert any("'production'" in p for p in problems)

    unsourced = {"text": "Improved accuracy by 35 percent", "evidence": "eval notebook"}
    assert any("number without a source" in p for p in audit_bullet(unsourced))

    team = {"text": "Built a search feature that we shipped in two sprints", "evidence": "repo"}
    assert any("not what the team did" in p for p in audit_bullet(team))

    result = coverage(["Python", "SQL", "RAG", "Kubernetes"], {"python", "sql", "rag"})
    assert result["gaps"] == ["Kubernetes"] and result["score"] == 0.75
    print("resume audit: all checks passed")


if __name__ == "__main__":
    check()

from typing import Dict, List, Sequence


def hit_at_k(retrieved: Sequence[str], relevant: set, k: int) -> float:
    """1.0 if any relevant id appears in the top k, else 0.0."""
    return 1.0 if any(r in relevant for r in retrieved[:k]) else 0.0


def reciprocal_rank(retrieved: Sequence[str], relevant: set) -> float:
    for i, r in enumerate(retrieved, start=1):
        if r in relevant:
            return 1.0 / i
    return 0.0


def evaluate(golden: List[dict], retrieve, k: int = 5) -> Dict[str, float]:
    """golden items: {"q": str, "relevant": [chunk ids]}. retrieve(q) -> ranked chunk ids."""
    if not golden:
        raise ValueError("golden set is empty")
    hits, rrs = [], []
    for item in golden:
        got = retrieve(item["q"])
        rel = set(item["relevant"])
        hits.append(hit_at_k(got, rel, k))
        rrs.append(reciprocal_rank(got, rel))
    n = len(golden)
    return {f"hit@{k}": sum(hits) / n, "mrr": sum(rrs) / n}


def index_problems(chunks: List[dict], expected_model: str, expected_dim: int,
                   expected_version: int) -> List[str]:
    """Report chunks that do not match the live embedding configuration.

    A query embedded with model B searched against vectors from model A returns
    plausible-looking nonsense, so this check belongs in the re-index job and in CI.
    """
    problems = []
    for c in chunks:
        if c["embed_model"] != expected_model:
            problems.append(f"chunk {c['id']}: model {c['embed_model']} != {expected_model}")
        if c["embed_dim"] != expected_dim:
            problems.append(f"chunk {c['id']}: dim {c['embed_dim']} != {expected_dim}")
        if c["index_version"] != expected_version:
            problems.append(f"chunk {c['id']}: version {c['index_version']} != {expected_version}")
    return problems


def test_rag_eval():
    golden = [
        {"q": "refund window", "relevant": ["c1"]},
        {"q": "manager approval", "relevant": ["c2"]},
        {"q": "salary band", "relevant": ["c3"]},
    ]
    answers = {
        "refund window": ["c9", "c1", "c4"],        # relevant at rank 2
        "manager approval": ["c2", "c1"],           # rank 1
        "salary band": ["c5", "c6", "c7"],          # miss
    }
    res = evaluate(golden, lambda q: answers[q], k=3)
    assert res["hit@3"] == 2 / 3
    assert abs(res["mrr"] - (0.5 + 1.0 + 0.0) / 3) < 1e-9
    assert evaluate(golden, lambda q: answers[q], k=1)["hit@1"] == 1 / 3
    try:
        evaluate([], lambda q: [])
        assert False
    except ValueError:
        pass

    chunks = [
        {"id": 1, "embed_model": "embed-v2", "embed_dim": 768, "index_version": 7},
        {"id": 5, "embed_model": "embed-v1", "embed_dim": 384, "index_version": 3},
    ]
    probs = index_problems(chunks, "embed-v2", 768, 7)
    assert len(probs) == 3 and all(p.startswith("chunk 5") for p in probs)
    assert index_problems(chunks[:1], "embed-v2", 768, 7) == []

from statistics import median
from typing import Dict, List

FIELDS = ["queue_ms", "ttft_ms", "decode_ms", "total_ms", "prompt_tokens", "completion_tokens"]


def summarize(calls: List[Dict[str, float]]) -> Dict[str, float]:
    """Median of each field across calls."""
    if not calls:
        raise ValueError("no calls")
    return {f: median(c[f] for c in calls) for f in FIELDS}


def explain_change(before: List[Dict[str, float]], after: List[Dict[str, float]]) -> Dict[str, object]:
    """Say which stage added the latency. total = queue + ttft + decode."""
    b, a = summarize(before), summarize(after)
    delta = {f: a[f] - b[f] for f in FIELDS}
    stages = {s: delta[s] for s in ("queue_ms", "ttft_ms", "decode_ms")}
    culprit = max(stages, key=lambda s: stages[s])
    note = {
        "queue_ms": "waiting for capacity: rate limits, retries, concurrency caps",
        "ttft_ms": "prefill: prompt got longer (check prompt_tokens) or cache stopped hitting",
        "decode_ms": "generation: output got longer (check completion_tokens) or a slower model",
    }[culprit]
    per_tok_before = b["decode_ms"] / b["completion_tokens"]
    per_tok_after = a["decode_ms"] / a["completion_tokens"]
    return {"delta": delta, "culprit": culprit, "note": note,
            "ms_per_output_token": (round(per_tok_before, 1), round(per_tok_after, 1))}


def _calls(n, queue, ttft, decode, p_tok, c_tok):
    return [{"queue_ms": queue, "ttft_ms": ttft, "decode_ms": decode, "total_ms": queue + ttft + decode,
             "prompt_tokens": p_tok, "completion_tokens": c_tok} for _ in range(n)]


def test_latency():
    # Prompt change asked for step-by-step reasoning: output tokens doubled, prefill unchanged.
    before = _calls(5, 20, 400, 1000, 800, 100)
    after = _calls(5, 20, 410, 2000, 820, 200)
    r = explain_change(before, after)
    assert r["culprit"] == "decode_ms" and r["delta"]["completion_tokens"] == 100
    assert r["ms_per_output_token"] == (10.0, 10.0)      # per-token speed unchanged: it is length, not the model

    # Long few-shot examples were added: prefill grew, output unchanged.
    after2 = _calls(5, 20, 1400, 1000, 4800, 100)
    assert explain_change(before, after2)["culprit"] == "ttft_ms"

    # Retries and rate limiting show up as queue time.
    after3 = _calls(5, 900, 400, 1000, 800, 100)
    assert explain_change(before, after3)["culprit"] == "queue_ms"

    # median ignores one outlier
    mixed = _calls(4, 20, 400, 1000, 800, 100) + _calls(1, 20, 400, 90000, 800, 100)
    assert summarize(mixed)["decode_ms"] == 1000
    try:
        summarize([])
        assert False
    except ValueError:
        pass
